package dev.betterparty.api.v1.client;

import java.util.Objects;
import net.minecraft.network.chat.Component;

public record PartyMemberHudRow(Component label, float value, float maximum, int barColorArgb) {
    public PartyMemberHudRow {
        Objects.requireNonNull(label, "label");
        if (!Float.isFinite(value) || !Float.isFinite(maximum) || value < 0.0f || maximum < 0.0f || maximum == 0.0f && value != 0.0f) {
            throw new IllegalArgumentException("Invalid member HUD row values");
        }
    }

    public static PartyMemberHudRow bar(Component label, float value, float maximum, int barColorArgb) {
        if (maximum <= 0.0f) {
            throw new IllegalArgumentException("A member HUD bar requires a positive maximum");
        }
        return new PartyMemberHudRow(label, value, maximum, barColorArgb);
    }

    public static PartyMemberHudRow text(Component label) {
        return new PartyMemberHudRow(label, 0.0f, 0.0f, 0);
    }

    public boolean hasBar() {
        return this.maximum > 0.0f;
    }

    public float ratio() {
        return this.hasBar() ? Math.max(0.0f, Math.min(1.0f, this.value / this.maximum)) : 0.0f;
    }
}

