private static boolean trackerRegistered;

private XaeroCompatibility() {
}

public static synchronized boolean registerPlayerTracker() {
    if (registrationAttempted) {
        return trackerRegistered;
    }
    registrationAttempted = true;
    try {
        Class<?> worldMapClass = Class.forName(WORLD_MAP_CLASS);
        Field managerField = worldMapClass.getField("playerTrackerSystemManager");
        Object manager = managerField.get(null);
        if (manager == null) {
            throw new IllegalStateException("Xaero player tracker manager is not initialized");
        }
        Object tracker = XaeroCompatibility.createTrackerProxy(worldMapClass.getClassLoader());
        Method registerMethod = XaeroCompatibility.findRegisterMethod(manager.getClass(), tracker);
        registerMethod.invoke(manager, "better_party_x_xaeros_world_map", tracker);
        trackerRegistered = true;
        BetterPartyXaerosWorldMap.LOGGER.info("Registered Better Party player tracking with Xaero's World Map");
    }
    catch (LinkageError | ReflectiveOperationException | RuntimeException failure) {
        BetterPartyXaerosWorldMap.LOGGER.error("Xaero's World Map integration is incompatible with the installed version. Party map markers are disabled, but the game can continue.", failure);
    }
    return trackerRegistered;
}

public static void reportRendererIncompatibility(Throwable failure) {
    if (RENDERER_FAILURE_REPORTED.compareAndSet(false, true)) {
        BetterPartyXaerosWorldMap.LOGGER.error("Xaero's marker renderer changed incompatibly. Custom dot rendering is disabled and Xaero's normal marker renderer will be used.", failure);
    }
